const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');
const sheet=new Image();sheet.src='charactersheet.png';
const rooms={outside:{name:'Vor der Garage',depth:7,info:'Vorplatz · Haus am Hang · Sektionaltor',floor:'#aaa495',wall:'#d5cdb5'},garage:{name:'Garage',depth:7,info:'Garage · ca. 4 × 7 m',floor:'#aaa495',wall:'#d5cdb5'},workshop:{name:'Werkstatt',depth:5,info:'Werkstatt · ca. 4 × 5 m · eine Stufe höher',floor:'#b5a68a',wall:'#e0cf9f'},oil:{name:'Öllager',depth:3,info:'Öllager · Größe vorläufig',floor:'#8b8c7b',wall:'#b5b49d'}};
const types={bench:{name:'Werkbank',icon:'🛠',w:1.35,d:.65},fridge:{name:'Kühlschrank',icon:'❄',w:.65,d:.65},beer:{name:'Bierkiste',icon:'🍺',w:.65,d:.5},tools:{name:'Werkzeugwagen',icon:'🔧',w:.8,d:.55},sofa:{name:'Sofa',icon:'🛋',w:1.5,d:.8},radio:{name:'Radio',icon:'♫',w:.5,d:.35}};
let state={room:'garage',person:'Dirk',items:[],positions:{Dirk:{x:2.4,z:4.5},Ela:{x:3.2,z:4.1}},selected:null,tool:null,rot:0};
try{const s=JSON.parse(localStorage.getItem('dirks-garage-v1'));if(s&&Array.isArray(s.items))state.items=s.items.filter(i=>types[i.type]&&rooms[i.room]&&Number.isFinite(i.x)&&Number.isFinite(i.z));}catch{}
let mouse=null,keys=new Set(),ready=location.protocol==='file:',saveQueue=Promise.resolve();
let chosen=false,path=[],destination=null,arrival=null,gateOpen=false;
state.hatchOpen=false;
const picker=document.createElement('dialog');picker.id='character-picker';picker.innerHTML=`<span class="eyebrow">WILLKOMMEN ZUR GABI</span><h2>Als wer kommst du vorbei?</h2><p>Wähle deine Figur für die heutige Runde.</p><div class="character-options"><button id="select-dirk"><span class="portrait dirk"><img src="charactersheet.png" alt="Dirk im blauen Hemd"></span>Dirk</button><button id="select-ela"><span class="portrait ela"><img src="charactersheet.png" alt="Ela im schwarzen Oberteil"></span>Ela</button></div>`;document.body.append(picker);
picker.addEventListener('cancel',e=>{if(!chosen)e.preventDefault();});
function selectPerson(name){state.person=name;chosen=true;path=[];destination=null;picker.close();document.querySelector('#current-person').textContent=name;say(name,name==='Dirk'?'So, auf zur Gabi!':'Ein Garagen-Bier mit euch? Bin dabei.');canvas.focus();render();}
for(const name of ['Dirk','Ela'])picker.querySelector('#select-'+name.toLowerCase()).onclick=()=>selectPerson(name);
document.querySelector('.people').innerHTML='<b id="current-person">Noch keine Figur gewählt</b><button id="change-person">Figur wechseln</button>';document.querySelector('#change-person').onclick=()=>{keys.clear();path=[];destination=null;picker.showModal();};
const oilView=document.createElement('dialog');oilView.id='oil-view';oilView.innerHTML=`<span class="eyebrow">BLICK DURCH DIE WANDLUKE</span><h2>Das Öllager</h2><svg viewBox="0 0 560 265" role="img" aria-label="Im Öllager stehen ausschließlich drei große Ölcontainer"><path d="M10 15h540v235H10z" fill="#b4b29e" stroke="#30352d" stroke-width="7"/><path d="M15 225h530" stroke="#777967" stroke-width="4"/><g fill="#7e8778" stroke="#30352d" stroke-width="4"><rect x="40" y="65" width="142" height="158" rx="25"/><rect x="208" y="65" width="142" height="158" rx="25"/><rect x="376" y="65" width="142" height="158" rx="25"/></g><g fill="none" stroke="#4a5749" stroke-width="6"><path d="M55 106h112M55 180h112M223 106h112M223 180h112M391 106h112M391 180h112M111 65V39H447V65M279 65V39"/></g><g fill="#e2d5a2" font-size="23" font-family="Arial" font-weight="bold"><text x="89" y="151">ÖL</text><text x="256" y="151">ÖL</text><text x="424" y="151">ÖL</text></g></svg><p>Hier stehen nur die Ölcontainer. Der Raum ist nicht begehbar.</p><button id="close-hatch">Luke schließen</button>`;document.body.append(oilView);
function closeHatch(){state.hatchOpen=false;oilView.close();render();canvas.focus();}
oilView.querySelector('button').onclick=closeHatch;oilView.addEventListener('cancel',e=>{e.preventDefault();closeHatch();});
function openHatch(){if(!chosen||!ready)return;path=[];destination=null;state.hatchOpen=true;oilView.showModal();render();}
document.querySelector('[data-room="oil"]').remove();
function blocked(x,z){if(state.room==='outside')return x<.2||x>3.8||z<4.5||z>6.8;if(x<.2||x>3.8||z<.45||z>rooms[state.room].depth-.2)return true;return state.items.some(i=>{const[w,d]=dims(i);return i.room===state.room&&x>i.x-.17&&x<i.x+w+.17&&z>i.z-.14&&z<i.z+d+.14;});}
function walkTo(x,z){arrival=null;const p=state.positions[state.person];if(blocked(x,z)){say(state.person,'Da ist kein Platz zum Stehen.');return;}const step=.1,start=[Math.round(p.x/step),Math.round(p.z/step)],goal=[Math.round(x/step),Math.round(z/step)],key=(x,z)=>x+','+z,queue=[start],seen=new Map([[key(...start),null]]);let found=false;for(let n=0;n<queue.length;n++){const[a,b]=queue[n];if(a===goal[0]&&b===goal[1]){found=true;break;}for(const[dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const u=a+dx,v=b+dz,k=key(u,v);if(!seen.has(k)&&!blocked(u*step,v*step)){seen.set(k,[a,b]);queue.push([u,v]);}}}if(!found){say(state.person,'Der Weg ist zugestellt.');return;}let at=goal,next=[];while(at){next.push({x:at[0]*step,z:at[1]*step});at=seen.get(key(...at));}next.reverse();next.push({x,z});path=next;destination={x,z};}
const saveStatus=document.createElement('small'),retry=document.createElement('button');saveStatus.id='save-status';saveStatus.setAttribute('role','status');retry.textContent='Erneut versuchen';retry.hidden=true;document.querySelector('aside small').replaceWith(saveStatus);saveStatus.after(retry);
function save(){try{localStorage.setItem('dirks-garage-v1',JSON.stringify({items:state.items}));}catch{}goals();if(location.protocol==='file:'){saveStatus.textContent='Nur in diesem Browser gespeichert. Für SQLite bitte den Server starten.';return;}if(!ready)return;const payload=JSON.stringify({items:state.items});saveStatus.textContent='Wird gespeichert …';saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{const r=await fetch('api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:payload});if(!r.ok)throw Error();saveStatus.textContent='Gespeichert · gemeinsamer Spielstand';retry.hidden=true;}catch{saveStatus.textContent='Speichern fehlgeschlagen. Einrichtung ist noch im Browser vorhanden.';retry.hidden=false;}});}
async function load(){if(location.protocol==='file:'){saveStatus.textContent='Lokaler Entwurf · Speicherung nur in diesem Browser';return;}try{saveStatus.textContent='Spielstand wird geladen …';const r=await fetch('api/state',{cache:'no-store'});if(!r.ok)throw Error();const s=await r.json();if(!Array.isArray(s.items))throw Error();state.items=s.items.filter(i=>types[i.type]&&rooms[i.room]);ready=true;goals();render();saveStatus.textContent='Geladen · gemeinsamer Spielstand';retry.hidden=true;}catch{ready=false;saveStatus.textContent='Spielstand nicht erreichbar. Bitte Server starten und erneut versuchen.';retry.hidden=false;}}
retry.onclick=()=>ready?save():load();
