function say(who,text){document.querySelector('#speaker').textContent=who;document.querySelector('#speech').textContent=text;}
function P(x,z,h=0){return{x:170+x*135+z*24,y:245+z*48-h};}
function poly(points,color,stroke='#30352d',width=3){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
