if(i.type==='bench'){box(x,z,w,d,65,'#91704d','#c89f64');box(x+.08,z+.08,.17,.17,4,'#555b59');let p=P(x+.3,z+.2,71);text('╱ 🔧',p.x,p.y,19);}
if(i.type==='fridge'){box(x,z,w,d,108,'#dbe3d3','#f1eedb');const a=P(x+.08,z+d,72),b=P(x+w-.08,z+d,72);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle='#4c5b55';ctx.lineWidth=3;ctx.stroke();const p=P(x+.12,z+d,56);text('┃',p.x,p.y,24);}
