if(i.type==='radio'){box(x,z,w,d,30,'#535f58','#788379');let p=P(x+.09,z+d,12);text('◉ ▤',p.x,p.y,16,'#e6d398');p=P(x+.1,z,32);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-8,p.y-30);ctx.strokeStyle='#30352d';ctx.lineWidth=2;ctx.stroke();}
