function door(x,width,label,kind){poly([P(x,0),P(x+width,0),P(x+width,0,125),P(x,0,125)],'#626d64');for(let h=22;h<120;h+=20){const a=P(x+.03,0,h),b=P(x+width-.03,0,h);ctx.strokeStyle='#7c887b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}const k=P(x+width-.12,0,58);ctx.fillStyle='#dacb7f';ctx.fillRect(k.x-10,k.y,11,4);const a=P(x,0,137);text(label,a.x-8,a.y,14);if(kind==='step'){box(x,0,width,.25,10,'#9e9b87','#d6c9a6');const p=P(x,0.4);text('↑ 1 Stufe',p.x,p.y+10,13);}}
