ctx.fillStyle='#94b3b4';ctx.strokeStyle='#526960';for(const[x,y,w,h]of [[405,140,106,42],[330,210,51,45],[510,210,98,45],[340,290,45,48],[535,279,27,23]]){ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h);}ctx.fillStyle='#9e8b6b';ctx.fillRect(435,285,35,65);ctx.strokeRect(435,285,35,65);ctx.fillStyle='#30352d';ctx.fillRect(461,318,4,4);
ctx.fillStyle='#343f37';ctx.fillRect(245,360,200,105);ctx.strokeStyle='#30352d';ctx.lineWidth=4;ctx.strokeRect(245,360,200,105);
