text(gateOpen?'Sektionaltor offen':'Sektionaltor öffnen',247,493,14);text('DIRKS GARAGE',735,325,26);text('Die GaBi wartet im Hinterzimmer.',713,351,14);text('Tor anklicken. Dann reingehen.',713,377,13);
