poly([{x:0,y:210},{x:150,y:112},{x:280,y:190},{x:475,y:70},{x:720,y:178},{x:1000,y:34},{x:1000,y:690},{x:0,y:690}],'#91a16d',null);for(let n=0;n<9;n++){let x=20+n*120,y=130+(n%3)*20;poly([{x,y:y-85},{x:x-30,y:y+15},{x:x+31,y:y+15}],'#52754c');ctx.fillStyle='#796343';ctx.fillRect(x-5,y+15,10,35);}poly([{x:0,y:645},{x:1000,y:645},{x:1000,y:690},{x:0,y:690}],'#787e76');ctx.setLineDash([28,23]);ctx.strokeStyle='#ddd6b8';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,673);ctx.lineTo(1000,673);ctx.stroke();ctx.setLineDash([]);
