text(r.name.toUpperCase(),530,123,30);text(state.room==='garage'?'Hier wird geschraubt. Und angestoßen.':state.room==='workshop'?'Alles hat seinen Platz. Irgendwann.':'Hinter der kleinen Stahltür.',530,149,14);
if(state.room==='garage')door(.65,.9,'ZUR WERKSTATT','step');if(state.room==='workshop')hatch();if(state.room==='oil'){box(2.05,.1,1.6,.8,95,'#747b68','#959b83');text('ÖLTANK',537,202,17);}
const ents=state.items.filter(i=>i.room===state.room).map(i=>({z:i.z+types[i.type].d,draw:()=>furniture(i)}));if(chosen)ents.push({z:state.positions[state.person].z,draw:()=>person(state.person)});ents.sort((a,b)=>a.z-b.z).forEach(e=>e.draw());
