function dims(i){const t=types[i.type];return i.rot?[t.d,t.w]:[t.w,t.d];}
function valid(i){if(state.room==='outside'||state.room==='oil')return false;const[w,d]=dims(i),D=rooms[state.room].depth;if(i.x<.05||i.x+w>3.95||i.z<.32||i.z+d>D-.1)return false;if(i.x<1.7&&i.x+w>.55&&i.z<1)return false;if(state.room==='oil'&&i.x+w>2&&i.z<1)return false;return !state.items.some(j=>j.room===state.room&&j.id!==state.selected&&(()=>{const[a,b]=dims(j);return i.x<j.x+a+.04&&i.x+w+.04>j.x&&i.z<j.z+b+.04&&i.z+d+.04>j.z;})());}
function setRoom(room){if(room==='oil')return;path=[];destination=null;arrival=null;state.room=room;state.selected=null;state.tool=null;state.positions={Dirk:{x:2.3,z:room==='outside'?6.2:rooms[room].depth-.9},Ela:{x:2.3,z:room==='outside'?6.2:rooms[room].depth-.9}};document.querySelectorAll('[data-room]').forEach(b=>b.classList.toggle('active',b.dataset.room===room));document.querySelector('#room-info').textContent=rooms[room].info;mode();say('Ela',room==='workshop'?'Willkommen zur Gabi! Garagen-Bier im Hinterzimmer.':room==='oil'?'Die Luke ist klein. Der Tank bleibt, wo er ist.':'So. Was kommt als Erstes rein?');render();}
function mode(){document.querySelector('#mode').textContent=state.tool?types[state.tool].name+' platzieren':'Spazieren & anschauen';document.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===state.tool));}
function choose(type){if(!chosen)return;if(state.room==='outside'){say(state.person,'Einrichten geht drinnen. Erst das Sektionaltor öffnen.');return;}path=[];destination=null;state.tool=type;state.selected=null;state.rot=0;mode();render();}
function coord(e){const b=canvas.getBoundingClientRect(),px=(e.clientX-b.left)*1000/b.width,py=(e.clientY-b.top)*690/b.height,z=(py-245)/48,x=(px-170-z*24)/135;return{x:Math.round(x*10)/10,z:Math.round(z*10)/10,py,px};}
canvas.addEventListener('pointermove',e=>{mouse=coord(e);render();});canvas.addEventListener('pointerleave',()=>{mouse=null;render();});
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;canvas.focus();const m=coord(e);if(state.room==='outside'){if(m.px>=245&&m.px<=445&&m.py>=348&&m.py<=465){if(!gateOpen){gateOpen=true;say(state.person,'Das Sektionaltor ist offen. Nochmal klicken zum Reingehen.');render();}else{walkTo(1,4.6);if(destination)arrival=()=>setRoom('garage');}return;}walkTo(m.x,m.z);render();return;}if(state.room==='workshop'&&m.px>=250&&m.px<=365&&m.py>=135&&m.py<=218){openHatch();return;}if(state.tool){const item={type:state.tool,x:m.x,z:m.z,rot:state.rot,room:state.room,id:state.selected||Date.now()};if(!valid(item)){say('Dirk','Da passt es nicht. Lass die Tür und etwas Platz zum Laufen frei.');return;}if(state.selected)state.items=state.items.filter(i=>i.id!==state.selected);state.items.push(item);state.selected=null;state.tool=null;save();mode();say(state.person,'Steht! So langsam wird’s meine Bude.');render();return;}
const hit=[...state.items].reverse().find(i=>{if(i.room!==state.room)return false;const p=P(i.x,i.z),[w,d]=dims(i);return m.px>=p.x-5&&m.px<=p.x+w*135+d*24+5&&m.py>=p.y-110&&m.py<=p.y+d*48+8;});if(hit){path=[];destination=null;state.selected=hit.id;state.tool=hit.type;state.rot=hit.rot;mode();render();return;}
if(m.z<.45&&m.x>.4&&m.x<1.8&&state.room==='garage'){walkTo(1.1,.5);if(destination)arrival=()=>setRoom('workshop');return;}if(m.z>rooms[state.room].depth){setRoom(state.room==='workshop'?'garage':'outside');return;}if(m.x>.15&&m.x<3.85&&m.z>.45&&m.z<rooms[state.room].depth-.1){walkTo(m.x,m.z);render();}});
document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{if(chosen)setRoom(b.dataset.room);});
for(const[type,t]of Object.entries(types)){const b=document.createElement('button');b.dataset.type=type;b.innerHTML=`<span aria-hidden="true">${t.icon}</span>${t.name}`;b.onclick=()=>choose(type);document.querySelector('#catalog').append(b);}
document.querySelector('#walk').onclick=()=>{state.tool=null;state.selected=null;mode();render();};document.querySelector('#reset').onclick=()=>{state.items=[];state.tool=null;state.selected=null;save();mode();say('Ela','Alles leer. Neue Runde!');render();};
document.addEventListener('keydown',e=>{if(picker.open||oilView.open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Delete',' '].includes(e.key))e.preventDefault();keys.add(e.key);if(e.repeat)return;if(e.key.toLowerCase()==='r'&&state.tool){state.rot=1-state.rot;render();}if(e.key==='Escape'){state.tool=null;state.selected=null;mode();render();}if(e.key==='Delete'&&state.selected){state.items=state.items.filter(i=>i.id!==state.selected);state.tool=null;state.selected=null;save();mode();render();}if(e.key.toLowerCase()==='f'){if(document.fullscreenElement)document.exitFullscreen();else canvas.requestFullscreen?.();}});document.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
function update(dt){if(!chosen||picker.open||oilView.open||state.tool)return;const p=state.positions[state.person],speed=2.2;const dx=Number(keys.has('ArrowRight'))-Number(keys.has('ArrowLeft')),dz=Number(keys.has('ArrowDown'))-Number(keys.has('ArrowUp'));if(dx||dz){path=[];destination=null;arrival=null;const n=Math.hypot(dx,dz),x=p.x+dx/n*dt*speed,z=p.z+dz/n*dt*speed;if(!blocked(x,z)){p.x=x;p.z=z;}return;}let budget=dt*speed;while(path.length&&budget>0){const t=path[0],distance=Math.hypot(t.x-p.x,t.z-p.z);if(blocked(t.x,t.z)){path=[];destination=null;arrival=null;return;}if(distance<=budget){p.x=t.x;p.z=t.z;budget-=distance;path.shift();}else{p.x+=(t.x-p.x)/distance*budget;p.z+=(t.z-p.z)/distance*budget;budget=0;}}if(!path.length&&destination){destination=null;const done=arrival;arrival=null;if(done)done();}}
function goals(){const has=t=>state.items.some(i=>i.type===t&&i.room==='workshop');document.querySelector('#goals').innerHTML=[['bench','Werkbank steht'],['fridge','Kühlschrank steht'],['beer','Bier ist da']].map(([t,s])=>`<div>${has(t)?'☑':'☐'} ${s}</div>`).join('');if(has('bench')&&has('fridge')&&has('beer'))say('Ela','Alles Gute, Dirk! Die Werkstatt ist bereit für die nächste Gabi.');}
window.render_game_to_text=()=>JSON.stringify({room:state.room,person:chosen?state.person:null,choosingCharacter:picker.open,hatchOpen:state.hatchOpen,gateOpen,destination,pathLength:path.length,visibleCharacters:chosen?[state.person]:[],positions:state.positions,items:state.items,tool:state.tool,selected:state.selected,rotation:state.rot,coordinates:'meters; x right 0..4, z from back wall toward entrance',stepToWorkshop:'one step up',doors:'left of center'});window.advanceTime=ms=>{update(ms/1000);render();};let last=performance.now();function loop(now){update(Math.min((now-last)/1000,.05));last=now;render();requestAnimationFrame(loop);}sheet.onload=render;sheet.onerror=()=>say('Ela','Das Charactersheet konnte nicht geladen werden.');goals();mode();setRoom('outside');load();picker.showModal();requestAnimationFrame(loop);

